/** One item parsed from a task spec's `## Success Criteria` section. */
export interface SuccessCriterionItem {
  /** 1-based position in document order — the spec's own numbering, as `SC<N>` refers to it. */
  number: number;
  /** The item's text, with wrapped continuation lines joined. */
  text: string;
}

/**
 * Matches the `## Success Criteria` heading and its body.
 *
 * Same boundary construction as the AT path's `ACCEPTANCE_TESTS_RE` (mt#3306 Defect 1 /
 * mt#3059 FP-1, plus PR #2386 R1's off-by-one fix): the section ends at the next heading of
 * the SAME OR DEEPER level (`##` or `###`), anchored on `^` in multiline mode so a heading
 * that immediately follows with ZERO content is still recognized as the boundary. The final
 * alternative uses `(?![\s\S])` rather than `$` because the `m` flag would otherwise make `$`
 * mean "end of any line".
 *
 * This matters here for the same reason it did there: `work-completion.mdc §Recovery layer
 * spec discipline` requires a `### Covers` / `### Does NOT cover` pair on exactly the kind of
 * infrastructure spec this check most wants to police, and a `###` boundary invisible to a
 * `\n##\s` lookahead would sweep those bullets in as criteria.
 */
const SUCCESS_CRITERIA_RE =
  /##\s*Success Criteria\s*\n([\s\S]*?)(?=^#{2,3}\s|^---[ \t]*$|(?![\s\S]))/im;

/** Extracts the raw body of a spec's `## Success Criteria` section, or null when absent. */
export function extractSuccessCriteriaSection(specContent: string): string | null {
  const match = specContent.match(SUCCESS_CRITERIA_RE);
  return match ? (match[1] ?? "") : null;
}

/**
 * Parses the section into numbered items.
 *
 * Recognizes the GitHub task-list form the `/create-task` template and this repo's specs
 * actually use (`- [ ] ...`), plain bullets, and explicitly numbered lists. Unlike the AT
 * parser, a written number is NOT preserved: `SC<N>` references are positional by convention,
 * and a spec whose criteria are checkboxes has no written numbers to preserve. Numbering is
 * therefore always sequential in document order starting at 1.
 *
 * Top-level items only — an indented bullet is a sub-point of the current criterion and folds
 * into its text, matching the AT parser's PR #2207 R1 behavior. A bolded lead-in
 * (`- [ ] **Injection at PR time.** ...`) is kept in the text; it is often where the
 * distinctive keywords live.
 */
export function parseSuccessCriteria(specContent: string): SuccessCriterionItem[] {
  const section = extractSuccessCriteriaSection(specContent);
  if (!section) return [];

  const items: SuccessCriterionItem[] = [];
  let current: SuccessCriterionItem | null = null;

  for (const rawLine of section.split("\n")) {
    // Top-level checkbox or bullet: `- [ ] text`, `- [x] text`, `- text`, `* text`.
    const bulletMatch = rawLine.match(/^[-*]\s+(?:\[[ xX]\]\s+)?(.*)$/);
    if (bulletMatch) {
      if (current) items.push(current);
      current = { number: items.length + 1, text: (bulletMatch[1] ?? "").trim() };
      continue;
    }
    const numberedMatch = rawLine.match(/^\d+\.\s+(.*)$/);
    if (numberedMatch) {
      if (current) items.push(current);
      current = { number: items.length + 1, text: (numberedMatch[1] ?? "").trim() };
      continue;
    }
    if (current && rawLine.trim().length > 0) {
      current.text = `${current.text} ${rawLine.trim()}`.trim();
    }
  }
  if (current) items.push(current);

  return items;
}

/**
 * Command shapes — the "shell-runnable check" half of the contract.
 *
 * Includes a BARE command verb, not only a backticked one: mt#3347's real criterion read
 * "a repo-wide grep for `<select` under `src/cockpit/web` … returns zero hits", where the
 * backticks wrap the search STRING and the command name sits in prose.
 */
const COMMAND_SHAPE_PATTERNS: readonly RegExp[] = [
  /`[^`]*\b(?:grep|rg|wc|find|ls|git\s+grep)\b[^`]*`/i,
  /\b(?:grep|ripgrep|rg|wc\s+-l|find|git\s+grep)\b/i,
  /^\s*\$\s+\S/m,
];

/**
 * Expected-result shapes — the other half. A criterion naming a command with no expected
 * outcome is not self-settling: you can run it, but nothing says what answer passes.
 */
const EXPECTED_RESULT_PATTERNS: readonly RegExp[] = [
  /\breturns?\s+(?:zero|no|\d+)\s+(?:hits|matches|results|lines|rows|files)\b/i,
  /\bthe\s+count\s+is\s+\d+\b/i,
  /\b(?:zero|0)\s+(?:hits|matches|occurrences|results)\b/i,
  /\bexit(?:s|\s+code)?\s+0\b/i,
  /\bis\s+empty\b/i,
];

/**
 * True when a criterion embeds a runnable check AND an expected result.
 *
 * **Both halves are REQUIRED (PR #2432 R1).** An earlier shape treated the two families as
 * alternatives, so a bare `$ bun test` line — a command with no stated expected outcome —
 * classified as executable. That contradicts the contract this check rests on: the point is
 * that such a criterion IS ITS OWN CHECK, and a command with no expected result cannot settle
 * anything by running it. The reviewer flagged the `$ <cmd>` case; the backticked-command
 * pattern had exactly the same gap, so both are fixed together rather than one instance.
 *
 * **The default is NON-executable, inverted from the AT classifier.**
 * `isExecutableAcceptanceTest` treats everything as executable and SUBTRACTS findings-shaped
 * text, which is right for an `## Acceptance Tests` list — those are behavioral by
 * construction. A `## Success Criteria` list is the opposite: mostly judgment-shaped prose
 * ("the control renders with cockpit surface tokens"), with the executable ones a sharp
 * minority. Inheriting the AT default would classify nearly every criterion executable and
 * bury the real signal in warnings nobody can act on — the mem#719 failure mode, where a
 * detector's unmatchable output trains readers to discount its correct output too.
 *
 * Under-flagging is the safe direction while this ships log-only; the calibration log is how
 * the pattern set gets widened on evidence.
 */
export function isExecutableSuccessCriterion(text: string): boolean {
  const trimmed = text.trim();
  if (!trimmed) return false;
  const hasCommand = COMMAND_SHAPE_PATTERNS.some((p) => p.test(trimmed));
  const hasExpectedResult = EXPECTED_RESULT_PATTERNS.some((p) => p.test(trimmed));
  return hasCommand && hasExpectedResult;
}

/**
 * Criterion numbers that have a dedicated `SC<N>` section in the PR body.
 *
 * This is acceptance test 7's mechanism, and the boundary agreed with mt#3339 (see mt#3350's
 * `## Overlap reconciliation`): THIS task owns `SC<N>` heading recognition because it defines
 * what an SC number means; mt#3339 keeps every other non-canonical heading (`## Testing`,
 * `## Design/Approach`). The real-world shape is mt#3149 / PR #2255, whose body carries a
 * `## SC3 (...) — re-verified, closed as already-resolved` section that the AT-path scanner
 * could not see.
 *
 * Matching on the HEADING rather than folding the section into the evidence text is the more
 * precise move: `collectHeadingSections` collects from AFTER the heading line, so the number —
 * the only part that identifies WHICH criterion the section is about — would be dropped.
 *
 * Fence-gated via {@link computeFenceInternalLines}, so an `## SC3` line inside pasted example
 * Markdown does not count.
 */
export function findScHeadingNumbers(prBody: string): Set<number> {
  const stripped = prBody.replace(/<!--[\s\S]*?-->/g, "");
  const lines = stripped.split("\n");
  const fenceInternal = computeFenceInternalLines(lines);
  const found = new Set<number>();

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (line === undefined || fenceInternal[i] || !isMarkdownHeading(line)) continue;
    const match = line.match(/^\s*#{1,6}\s+SC\s*#?(\d+)\b/i);
    if (!match) continue;
    const n = parseInt(match[1] ?? "", 10);
    if (Number.isFinite(n)) found.add(n);
  }
  return found;
}

const CRITERION_STOPWORDS = new Set([
  "about",
  "after",
  "again",
  "before",
  "being",
  "block",
  "criterion",
  "doesn",
  "should",
  "their",
  "there",
  "these",
  "those",
  "which",
  "while",
]);

/** Lowercase, length>=5, non-stopword tokens used for loose keyword matching. */
function extractSignificantKeywords(text: string): string[] {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, " ")
    .split(/\s+/)
    .filter((word) => word.length >= 5 && !CRITERION_STOPWORDS.has(word));
}

/**
 * The accepted written forms of a criterion-number reference, as ONE list.
 *
 * Both users derive from it: {@link isCriterionReferencedByNumber} instantiates each form with a
 * specific number, and {@link extractReferencedCriterionNumbers} instantiates the same forms with
 * a capture group to read whatever number a line carries.
 *
 * They were two hand-mirrored lists for one round of PR #3082 and it produced exactly the defect
 * that shape produces: the region STARTER accepted all four forms while the region TERMINATOR
 * matched only `SC<N>`, so an adjacent `Criterion 2:` or `sc-2:` line with no blank line before
 * it bled into the previous criterion's region — mis-attributing evidence and risking a false
 * `disagrees`, which is the outcome this whole surface is built to avoid.
 */
const CRITERION_NUMBER_REFERENCE_FORMS: readonly ((n: string) => RegExp)[] = [
  (n) => new RegExp(`\\bSC\\s*#?${n}\\b`, "i"),
  (n) => new RegExp(`\\bsuccess criterion\\s*#?${n}\\b`, "i"),
  (n) => new RegExp(`\\bcriterion\\s*#?${n}\\b`, "i"),
  (n) => new RegExp(`\\bsc-${n}\\b`, "i"),
];

/** True when the evidence text references this criterion by number, in any common form. */
export function isCriterionReferencedByNumber(
  criterion: SuccessCriterionItem,
  evidenceText: string
): boolean {
  return CRITERION_NUMBER_REFERENCE_FORMS.some((form) =>
    form(String(criterion.number)).test(evidenceText)
  );
}

/** Every criterion number a line references, in any of the accepted forms. */
export function extractReferencedCriterionNumbers(line: string): number[] {
  const found: number[] = [];
  for (const form of CRITERION_NUMBER_REFERENCE_FORMS) {
    const n = parseInt(line.match(form("(\\d+)"))?.[1] ?? "", 10);
    if (Number.isFinite(n) && !found.includes(n)) found.push(n);
  }
  return found;
}

/** True when the evidence text shares a distinctive keyword with the criterion's own text. */
export function isCriterionReferencedByKeyword(
  criterion: SuccessCriterionItem,
  evidenceText: string
): boolean {
  const lower = evidenceText.toLowerCase();
  return extractSignificantKeywords(criterion.text).some((k) => lower.includes(k));
}

/**
 * Extracts the deferral target from a `[scN-deferred: mt#NNNN]` marker for THIS criterion
 * number, anywhere in the PR body.
 *
 * The marker is per-criterion and NUMBERED, mirroring the AT path's `[atN-deferred:]`
 * verbatim. An earlier draft of mt#3350's spec wrote a bare `[sc-deferred: ...]`; that shape
 * cannot target one criterion, so a single marker would have excused an entire list — which is
 * exactly the "prose explaining why it was skipped reads as coverage" failure the marker
 * convention exists to prevent.
 */
export function extractScDeferralMarker(prBody: string, criterionNumber: number): string | null {
  const match = prBody.match(new RegExp(`\\[sc${criterionNumber}-deferred:\\s*([^\\]]+)\\]`, "i"));
  return match ? (match[1] ?? "").trim() : null;
}

/** True when a `[scN-deferred: ...]` marker exists for this criterion number. */
export function isCriterionDeferred(prBody: string, criterionNumber: number): boolean {
  return extractScDeferralMarker(prBody, criterionNumber) !== null;
}

/**
 * Count-bearing expected-result shapes, with the value CAPTURED (mt#4214).
 *
 * Deliberately a SUBSET of {@link EXPECTED_RESULT_PATTERNS}, never a superset: this list must
 * not widen the executable-criterion CLASSIFICATION, which decides the population the whole
 * surface measures. Widening that set is a different change with a different blast radius.
 *
 * Two of the five classifier shapes are excluded because what they assert is not a count —
 * `exit code 0` (a process status) and `is empty` (a state whose evidence side has no number to
 * read). Both land as `not-comparable`, which is a classification, not a parse failure.
 */
const COUNT_CAPTURE_PATTERNS: readonly RegExp[] = [
  /\breturns?\s+(zero|no|\d+)\s+(?:hits|matches|results|lines|rows|files)\b/i,
  /\bthe\s+count\s+is\s+(\d+)\b/i,
  /\b(zero|0)\s+(?:hits|matches|occurrences|results)\b/i,
];

/** `zero` / `no` / a digit string to a number; anything else to null. */
function parseCountToken(token: string | undefined): number | null {
  if (!token) return null;
  const lower = token.toLowerCase();
  if (lower === "zero" || lower === "no") return 0;
  const n = parseInt(lower, 10);
  return Number.isFinite(n) ? n : null;
}

/**
 * The count a text ASSERTS, or null when it asserts none.
 *
 * ONE shared extractor for the criterion side, reused by {@link extractReportedCount} for the
 * evidence side, so the two cannot drift apart — the mt#4070 hazard, where four hand-mirrored
 * matchers diverged on each widening.
 *
 * A DISTRIBUTIVE expected result (`one hit per subcommand action`) returns null by construction:
 * resolving it needs the cardinality of the thing being distributed over, which is not in the
 * text. That is the mt#4076 shape, and it stays out of the comparable set on purpose.
 */
export function extractAssertedCount(text: string): number | null {
  for (const pattern of COUNT_CAPTURE_PATTERNS) {
    const parsed = parseCountToken(text.match(pattern)?.[1]);
    if (parsed !== null) return parsed;
  }
  return null;
}

/**
 * The count an EVIDENCE region reports, or null when none is unambiguously readable.
 *
 * Two shapes, in order. First a phrase the criterion side would also recognize
 * (`returns 3 matches`). Then a BARE integer on a line of its own — which is what `wc -l` and
 * `grep -c` actually print, and the reason the criterion-side extractor alone cannot read an
 * evidence block.
 *
 * **More than one bare integer is `null`, not the first one.** Pasted output routinely carries
 * several numbers, and picking one would manufacture a confident wrong pairing — the failure
 * mode this whole surface exists to avoid (mem#719: a detector whose incorrect output trains
 * readers to discount its correct output).
 */
export function extractReportedCount(region: string): number | null {
  const phrase = extractAssertedCount(region);
  if (phrase !== null) return phrase;
  const bare = region
    .split("\n")
    .map((l) => l.trim())
    .filter((l) => /^\d+$/.test(l));
  return bare.length === 1 ? parseInt(bare[0] ?? "", 10) : null;
}

/**
 * True when a line names a criterion OTHER than this one, in ANY accepted reference form.
 *
 * Uses the same {@link CRITERION_NUMBER_REFERENCE_FORMS} the region starter uses — see that
 * constant for why symmetry here is load-bearing rather than tidy.
 */
function referencesADifferentCriterion(line: string, ownNumber: number): boolean {
  return extractReferencedCriterionNumbers(line).some((n) => n !== ownNumber);
}

/**
 * The bounded region of text whose reported count belongs to THIS criterion, or null.
 *
 * Comparing an expected value to an actual one presupposes knowing which number in a free-form
 * evidence block belongs to criterion N, and the module had no such mechanism. A loose rule
 * would be worse than none, so attribution is bounded to two regions and falls through to null:
 *
 * 1. A dedicated `SC<N>` heading section in the PR body — bounded by construction.
 * 2. Otherwise, the evidence lines that reference the criterion BY NUMBER, plus the block
 *    directly beneath them, stopping at a blank line or a different criterion's number.
 *
 * Keyword association is deliberately NOT an attribution basis: it is the loosest of the four
 * presence tests {@link checkSuccessCriteriaCoverage} already applies, and it is exactly where a
 * wrong pairing would come from.
 */
export function resolveEvidenceRegion(
  criterion: SuccessCriterionItem,
  prBody: string,
  evidenceText: string
): string | null {
  const stripped = prBody.replace(/<!--[\s\S]*?-->/g, "");
  const bodyLines = stripped.split("\n");
  const headingPattern = new RegExp(`^\\s*#{1,6}\\s+SC\\s*#?${criterion.number}\\b`, "i");
  const section = collectHeadingSections(bodyLines, computeFenceInternalLines(bodyLines), (l) =>
    headingPattern.test(l)
  );
  if (section.length > 0) return section.join("\n");

  const evidenceLines = evidenceText.split("\n");
  const region: string[] = [];
  for (let i = 0; i < evidenceLines.length; i++) {
    const line = evidenceLines[i];
    if (line === undefined || !isCriterionReferencedByNumber(criterion, line)) continue;
    region.push(line);
    for (let j = i + 1; j < evidenceLines.length; j++) {
      const next = evidenceLines[j];
      if (next === undefined || next.trim() === "") break;
      if (referencesADifferentCriterion(next, criterion.number)) break;
      region.push(next);
    }
  }
  return region.length > 0 ? region.join("\n") : null;
}

/** An executable criterion whose evidence reports a count other than the one it asks for. */
export interface ScDisagreement {
  criterion: SuccessCriterionItem;
  /** The count the criterion's own text asks for. */
  expected: number;
  /** The count its bounded evidence region reports. */
  actual: number;
}

/** Result of cross-referencing a task's executable success criteria against a PR body. */
export interface ScCoverageResult {
  /** False when the task has zero executable criteria — the check does not apply. */
  applicable: boolean;
  /** Criteria classified executable (after the positive-match filter). */
  executableCriteria: SuccessCriterionItem[];
  /** Executable criteria neither addressed in the evidence nor deferred. */
  unaddressedCriteria: SuccessCriterionItem[];
  /**
   * The subset of `unaddressedCriteria` that IS referenced by number somewhere in the PR
   * body, just not in the evidence text the gate reads (mt#3339, mt#3566 design note 2).
   *
   * The sibling of `AtCoverageResult.presentElsewhereAts` — same absent-vs-location-gap
   * partition, same number-reference-only probe, same log-only posture. Carried here
   * deliberately rather than left for a later task: this surface had produced ZERO
   * calibration records when mt#3339 was planned, so its rate is only measurable
   * PROSPECTIVELY. A field added after the corpus accumulates cannot retro-classify it.
   */
  presentElsewhereCriteria: SuccessCriterionItem[];
  /**
   * Addressed criteria whose bounded evidence region reports a count OTHER than the one the
   * criterion asks for (mt#4214).
   *
   * A distinct population from `unaddressedCriteria`, not a subset of it: these criteria ARE
   * referenced, with real output pasted — which is exactly what makes them invisible to the
   * presence tests above. mt#4076 / PR #3047 is the worked instance.
   */
  disagreeingCriteria: ScDisagreement[];
  /**
   * Addressed criteria the comparison could not settle either way — no literal expected count,
   * no bounded evidence region, or no unambiguously readable reported count.
   *
   * Recorded rather than dropped so the size of the un-comparable population is MEASURABLE. If
   * it dominates, that is the input to deciding whether resolving distributive expectations is
   * worth building; silently omitting it would make the comparison look more complete than it is.
   */
  notComparableCriteria: SuccessCriterionItem[];
}

/**
 * Core coverage check (pure, injectable — mirrors `checkAcceptanceTestCoverage`'s shape).
 *
 * `evidenceText` is supplied by the caller rather than extracted here; see this module's
 * header for why importing the evidence hook would be a cycle.
 *
 * A criterion counts as addressed when ANY of these holds:
 *   - a `[scN-deferred: mt#NNNN]` marker exists for it anywhere in the PR body, OR
 *   - the PR body has a dedicated `SC<N>` heading section for it, OR
 *   - the evidence text references it by number, OR
 *   - the evidence text shares a distinctive keyword with its text.
 */
export function checkSuccessCriteriaCoverage(
  specContent: string,
  prBody: string,
  evidenceText: string
): ScCoverageResult {
  const all = parseSuccessCriteria(specContent);
  const executableCriteria = all.filter((c) => isExecutableSuccessCriterion(c.text));

  if (executableCriteria.length === 0) {
    return {
      applicable: false,
      executableCriteria: [],
      unaddressedCriteria: [],
      presentElsewhereCriteria: [],
      disagreeingCriteria: [],
      notComparableCriteria: [],
    };
  }

  const scHeadings = findScHeadingNumbers(prBody);
  const unaddressedCriteria = executableCriteria.filter((c) => {
    if (isCriterionDeferred(prBody, c.number)) return false;
    if (scHeadings.has(c.number)) return false;
    if (isCriterionReferencedByNumber(c, evidenceText)) return false;
    if (isCriterionReferencedByKeyword(c, evidenceText)) return false;
    return true;
  });

  // Number-reference-only against the FULL body, per mt#3566 design note 1 — the keyword
  // matcher over a whole PR body is near-certainly all-positive and would carry no signal.
  const presentElsewhereCriteria = unaddressedCriteria.filter((c) =>
    isCriterionReferencedByNumber(c, prBody)
  );

  // The agreement pass (mt#4214) runs over the ADDRESSED criteria — the ones the four presence
  // tests above already cleared. An unaddressed criterion has no evidence to compare against, so
  // the two populations are disjoint by construction rather than by filtering.
  const unaddressedNumbers = new Set(unaddressedCriteria.map((c) => c.number));
  const disagreeingCriteria: ScDisagreement[] = [];
  const notComparableCriteria: SuccessCriterionItem[] = [];

  for (const criterion of executableCriteria) {
    if (unaddressedNumbers.has(criterion.number)) continue;
    const expected = extractAssertedCount(criterion.text);
    const region =
      expected === null ? null : resolveEvidenceRegion(criterion, prBody, evidenceText);
    const actual = region === null ? null : extractReportedCount(region);
    if (expected === null || actual === null) {
      notComparableCriteria.push(criterion);
      continue;
    }
    if (expected !== actual) disagreeingCriteria.push({ criterion, expected, actual });
  }

  return {
    applicable: true,
    executableCriteria,
    unaddressedCriteria,
    presentElsewhereCriteria,
    disagreeingCriteria,
    notComparableCriteria,
  };
}

// ---------------------------------------------------------------------------
// mt#4829 — a criterion asserted MET while its own evidence is deferred
// ---------------------------------------------------------------------------

/**
 * One PR-body line asserting a criterion satisfied AND deferring the evidence for it.
 *
 * The conjunction is the finding. Either half alone is ordinary and correct: "SC3 — met" is a
 * normal claim, and "SC3 — deferred to mt#N" is the sanctioned way to defer one. Together in a
 * single entry they contradict — *met* says the criterion holds, *post-merge* concedes the
 * measurement that would establish it has not been taken — and the pair reads as thorough
 * because it names a follow-up.
 *
 * Originating instance, from mt#4804's merged PR body (#3517):
 *
 * > **SC3** — met by construction, confirmed post-merge. Registering **is** the backfill: …
 *
 * It was false. The cited mechanism was real and the SCOPE was not, and the line shipped through
 * self-verification, a bot review and the merge gate.
 */
export interface AssertDeferFinding {
  /** The criterion number the line references. */
  criterionNumber: number;
  /** The offending line, whitespace-collapsed. */
  line: string;
  /** The assertion token that matched. */
  assertion: string;
  /** The deferral token that matched. */
  deferral: string;
}

/** Any reference to a criterion by number, in the forms this repo's PR bodies actually use. */
const SC_LINE_REF_RE = /\bSC\s?#?(\d+)\b/i;

/** Asserts the criterion HOLDS. */
const ASSERTION_RE = /\b(?:met|satisfied|done|complete)\b/i;

/**
 * Concedes the establishing measurement has NOT been taken.
 *
 * `deferred` is here and is safe: the sanctioned `[scN-deferred: mt#NNNN]` marker is matched and
 * excluded first, so the bare word only reaches this set in prose form.
 */
const DEFERRAL_RE =
  /\b(?:post-merge|after\s+merge|will\s+verify|confirmed\s+later|deferred|to\s+be\s+verified)\b/i;

/**
 * Forms this check must NOT flag, because they are the answers it wants authors to give.
 *
 * - `[scN-deferred: mt#NNNN]` — the machine-visible deferral the SC-coverage gate already honours.
 * - `UNVERIFIED` — the label `/implement-task` §7a requires for an un-runnable live exercise.
 *
 * Flagging either would train authors away from the right answer, which is what SC2 forbids.
 */
const SANCTIONED_RE = /\[sc\d+-deferred:\s*[^\]]+\]|\bUNVERIFIED\b/i;

/**
 * A NEGATED assertion is not an assertion, and this guard is measured rather than defensive.
 *
 * Over 100 merged PRs the naive conjunction produced exactly one false positive, PR #3519's
 * *"**SC4 is NOT MET**, and is now deferred to an owner rather than merely…"* — an explicit
 * non-satisfaction plus an explicit owned deferral, which is the ideal authoring form. `MET`
 * matched the assertion set and `deferred` matched the deferral set, so the pair fired on the
 * one line in the corpus that most deserved not to be flagged. With this guard, precision on
 * that corpus goes from 1 of 2 to 1 of 1.
 */
const NEGATED_ASSERTION_RE =
  /\b(?:not\s+(?:yet\s+)?(?:met|satisfied|done|complete)|unmet|isn't\s+met|is\s+not\s+met)\b/i;

/**
 * Find criterion lines that assert satisfaction and defer their own evidence.
 *
 * **Scope is the PR body's SC-REFERENCING LINES, not a `## Success criteria` section.** Measured
 * over the last 100 merged PRs: 89 reference a criterion by number, while only 5 carry such a
 * section and 6 carry an `SC<N>` heading. Keying on the section would have shipped a check with a
 * 5% ceiling and no way to notice it — mem#704's can't-fail probe.
 *
 * Fenced blocks are elided first: a pasted run log or a quoted body is not this PR's own claim.
 */
export function findAssertDeferConjunctions(prBody: string): AssertDeferFinding[] {
  const withoutFences = prBody.replace(
    /^[ \t]{0,3}(`{3,}|~{3,})[\s\S]*?^[ \t]{0,3}\1[ \t]*$/gm,
    ""
  );

  const findings: AssertDeferFinding[] = [];
  for (const rawLine of withoutFences.split(/\n/)) {
    const line = rawLine.replace(/\s+/g, " ").trim();
    if (line.length === 0) continue;

    const ref = line.match(SC_LINE_REF_RE);
    if (!ref) continue;

    // Sanctioned forms are checked BEFORE the conjunction, so `[scN-deferred: …]` can never
    // reach the deferral set as a bare `deferred`.
    if (SANCTIONED_RE.test(line)) continue;
    if (NEGATED_ASSERTION_RE.test(line)) continue;

    const assertion = line.match(ASSERTION_RE);
    const deferral = line.match(DEFERRAL_RE);
    if (!assertion || !deferral) continue;

    const criterionNumber = Number(ref[1]);
    if (!Number.isInteger(criterionNumber)) continue;

    findings.push({
      criterionNumber,
      line,
      assertion: assertion[0],
      deferral: deferral[0],
    });
  }
  return findings;
}

/** Override env var (registered in `HOOK_ONLY_ENV_VARS`) — skips the SC-coverage check. */
export const SC_COVERAGE_SKIP_ENV_VAR = "MINSKY_SKIP_SC_COVERAGE";

/** Calibration log path (mt#2263 ladder) — repo-root relative. */
export const SC_COVERAGE_CALIBRATION_LOG =
  ".minsky/execution-evidence-sc-coverage-calibration.jsonl";

/** True when the SC-coverage check is skipped via env var. */
export function isScCoverageSkipped(env: NodeJS.ProcessEnv = process.env): boolean {
  const v = env[SC_COVERAGE_SKIP_ENV_VAR];
  return v === "1" || v?.toLowerCase() === "true" || v?.toLowerCase() === "yes";
}

/** Result of running the SC-coverage calibration surface for one merge attempt. */
export interface ScCoverageCalibrationRunResult {
  /** True when the check actually ran (not skipped, spec content present). */
  ranCheck: boolean;
  /** A WARN string for `additionalContext`, if any executable criterion is unaddressed. */
  warning?: string;
  /** The record to append to the calibration log, when there is one. */
  calibrationRecord?: Record<string, unknown>;
}

/**
 * Runs the SC-coverage calibration for one merge attempt and returns what the caller should
 * emit — never performs I/O of its own, so the caller owns both the log write and the warning.
 *
 * Log-only by construction (mt#2263 ladder): this returns a warning, never a deny, and the
 * caller must never let it alter the gate's blocking decision.
 */
export function runScCoverageCalibration(
  task: string,
  prNumber: number,
  specContent: string,
  prBody: string,
  evidenceText: string,
  env: NodeJS.ProcessEnv = process.env
): ScCoverageCalibrationRunResult {
  if (isScCoverageSkipped(env)) return { ranCheck: false };

  // mt#4829 — computed BEFORE the coverage result and independent of `applicable`. This finding
  // is decidable from the PR body's claim text alone: it needs no expected value, no actual
  // value, and no pairing between them, so it must not inherit the applicability of a classifier
  // (`isExecutableSuccessCriterion`) whose own reach is what mt#4219 questions.
  const assertDeferFindings = findAssertDeferConjunctions(prBody);
  const hasAssertDefer = assertDeferFindings.length > 0;

  let coverage: ScCoverageResult;
  try {
    coverage = checkSuccessCriteriaCoverage(specContent, prBody, evidenceText);
  } catch {
    // Fail silent, matching the AT path: a parse failure must never surface as a WARN and
    // never as a block (mt#3033 constraint 3).
    return { ranCheck: false };
  }

  const hasUnaddressed = coverage.unaddressedCriteria.length > 0;
  const hasDisagreement = coverage.disagreeingCriteria.length > 0;
  const hasCoverageFinding = coverage.applicable && (hasUnaddressed || hasDisagreement);
  if (!hasCoverageFinding && !hasAssertDefer) {
    return { ranCheck: true };
  }

  const list = coverage.unaddressedCriteria
    .map((c) => `  - SC${c.number}: ${truncateForWarning(c.text)}`)
    .join("\n");

  const unaddressedPart = hasUnaddressed
    ? `${coverage.unaddressedCriteria.length} of ${coverage.executableCriteria.length} ` +
      `mechanically-executable success criteria for ${task} are not addressed by the ` +
      `\`Execution evidence:\` block (no number/keyword reference, no \`SC<N>\` section, and no ` +
      `\`[scN-deferred: mt#NNNN]\` marker):\n${list}\n\n` +
      `These criteria name a command and an expected result — running one costs a second and is ` +
      `the only thing that settles it.`
    : "";

  // The disagreement half (mt#4214) is a DIFFERENT finding with a different remedy: the
  // criterion was referenced and its command was run, and the output says something other than
  // what the criterion asks for. Naming them separately matters — telling an author to "run the
  // command" when they already ran it is the noise that trains readers to discount the surface.
  const disagreementList = coverage.disagreeingCriteria
    .map(
      (d) =>
        `  - SC${d.criterion.number}: asks for ${d.expected}, evidence reports ${d.actual} — ` +
        `${truncateForWarning(d.criterion.text)}`
    )
    .join("\n");

  const disagreementPart = hasDisagreement
    ? `${coverage.disagreeingCriteria.length} criterion(s) for ${task} were addressed with real ` +
      `output that DISAGREES with the count the criterion states:\n${disagreementList}\n\n` +
      `Either the implementation does not yet satisfy the criterion, or the criterion's own text ` +
      `is stale and should be amended — recording the divergence elsewhere does not reconcile it ` +
      `(mem#986).`
    : "";

  // mt#4829: a THIRD finding class, and its remedy differs from both siblings. "Unreferenced"
  // says run the command; "disagrees" says reconcile the number. This one says the entry
  // contradicts itself — pick which half is true, then either produce the evidence or use the
  // sanctioned `[scN-deferred: mt#NNNN]` / `UNVERIFIED` form.
  const assertDeferList = assertDeferFindings
    .map(
      (f) =>
        `  - SC${f.criterionNumber}: asserts "${f.assertion}" and defers with "${f.deferral}" — ` +
        `${truncateForWarning(f.line)}`
    )
    .join("\n");

  const assertDeferPart = hasAssertDefer
    ? `${assertDeferFindings.length} criterion entry(s) for ${task} assert satisfaction AND defer ` +
      `their own evidence in the same line:\n${assertDeferList}\n\n` +
      `The two halves contradict: "met" says the criterion holds, while the deferral concedes the ` +
      `measurement that would establish it has not been taken — and the pair reads as thorough ` +
      `because it names a follow-up. Either produce the evidence now, or drop the assertion and ` +
      `use \`[sc<N>-deferred: mt#NNNN]\` or an \`UNVERIFIED\` label with its reason.`
    : "";

  const warning =
    `[execution-evidence-sc-coverage] CALIBRATION (log-only, mt#3350/mt#4214/mt#4829 — would ` +
    `block if graduated): ` +
    `${[unaddressedPart, disagreementPart, assertDeferPart].filter(Boolean).join("\n\n")}\n\n` +
    `Merge is NOT blocked by this. Override: set ${SC_COVERAGE_SKIP_ENV_VAR}=1.`;

  return {
    ranCheck: true,
    warning,
    calibrationRecord: {
      timestamp: new Date().toISOString(),
      task,
      prNumber,
      surface: "execution-evidence-sc-coverage",
      // mt#3607: same capture as the AT sibling, and for the same reason — the
      // verdict is computed from a mutable spec and a mutable PR body. This log
      // held ZERO records at capture time, so every record it ever accumulates
      // is auditable; that is the cheapest moment this fix will ever be
      // available, not a reason to skip it.
      [CAPTURE_SCHEMA_FIELD]: CAPTURE_SCHEMA_VERSION,
      judgedPrBody: captureArtifact(prBody),
      judgedSpec: captureArtifact(specContent),
      judgedEvidenceText: captureArtifact(evidenceText),
      executableCriterionCount: coverage.executableCriteria.length,
      unaddressedCriteria: coverage.unaddressedCriteria.map((c) => ({
        number: c.number,
        text: c.text,
      })),
      // mt#3339 (FP-4 partition), sibling of the AT surface's `presentElsewhereAts`.
      presentElsewhereCriteria: coverage.presentElsewhereCriteria.map((c) => ({
        number: c.number,
        text: c.text,
      })),
      // mt#4214: the finding CLASS, so `/calibration-review` can rate the two populations
      // separately. A shared FP rate over "never ran it" and "ran it, the output disagrees"
      // would be uninterpretable — the remedies differ, so a reviewer's judgment differs too.
      findingClasses: [
        ...(hasUnaddressed ? ["unreferenced"] : []),
        ...(hasDisagreement ? ["disagrees"] : []),
        // mt#4829 — rated separately for the same reason the first two are: its remedy is
        // "reconcile the entry with itself", not "run the command" or "fix the number", so a
        // shared FP rate across the three would be uninterpretable.
        ...(hasAssertDefer ? ["asserted-met-evidence-deferred"] : []),
      ],
      assertDeferFindings: assertDeferFindings.map((f) => ({
        number: f.criterionNumber,
        line: f.line,
        assertion: f.assertion,
        deferral: f.deferral,
      })),
      disagreeingCriteria: coverage.disagreeingCriteria.map((d) => ({
        number: d.criterion.number,
        text: d.criterion.text,
        expected: d.expected,
        actual: d.actual,
      })),
      // The SIZE of the un-comparable population, so its share is measurable rather than
      // implied. If it dominates, that is the evidence for deciding whether resolving
      // distributive expectations is worth building — see mt#4214's `## The limit this ships with`.
      notComparableCriterionCount: coverage.notComparableCriteria.length,
    },
  };
}

/** Criteria in this repo run long; the warning names them without reproducing a paragraph. */
function truncateForWarning(text: string, max = 160): string {
  const flat = text.replace(/\s+/g, " ").trim();
  return flat.length <= max ? flat : `${flat.slice(0, max - 1)}…`;
}
